BEGIN;
CREATE FUNCTION pg_temp.assert_fails(p_sql text,p_part text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE blocked boolean:=false;
BEGIN
 BEGIN EXECUTE p_sql;
 EXCEPTION WHEN OTHERS THEN IF position(p_part IN SQLERRM)=0 THEN RAISE EXCEPTION 'Falha inesperada: %',SQLERRM; END IF; blocked:=true;
 END;
 IF NOT blocked THEN RAISE EXCEPTION 'Operação fiscal indevidamente permitida'; END IF;
END $$;
INSERT INTO auth.users(id) VALUES('10000000-0000-0000-0000-000000000011'),('10000000-0000-0000-0000-000000000012');
INSERT INTO restaurants(id,slug,cnpj) VALUES('20000000-0000-0000-0000-000000000011','fiscal-issuance-test','12345678000195');
INSERT INTO user_roles(user_id,restaurant_id,role) VALUES('10000000-0000-0000-0000-000000000011','20000000-0000-0000-0000-000000000011','owner'),('10000000-0000-0000-0000-000000000012','20000000-0000-0000-0000-000000000011','cashier');
INSERT INTO pdv_menu_items(id,restaurant_id,code) VALUES('30000000-0000-0000-0000-000000000011','20000000-0000-0000-0000-000000000011','P1');
INSERT INTO restaurant_tables(restaurant_id,number,session_token) VALUES('20000000-0000-0000-0000-000000000011','3','fiscal-issuance-session');
INSERT INTO table_bill_items(restaurant_slug,table_number,item_code,item_name,unit_price,ordered_quantity,paid_portion,reserved_portion) VALUES('fiscal-issuance-test','3','P1','Produto de teste',10,2,2,0);
INSERT INTO table_payment_requests(id,restaurant_slug,table_number,payment_target,payment_method,status,amount,item_quantities,idempotency_key,service_fee_amount,establishment_method,provider) VALUES('40000000-0000-0000-0000-000000000011','fiscal-issuance-test','3','restaurant','at_establishment','approved',20,'{"P1":2}','payment-fixture',0,'cash','estabelecimento');
SELECT archive_and_reopen_table('fiscal-issuance-test','3');
DO $$
DECLARE rid uuid:='20000000-0000-0000-0000-000000000011'; actor uuid:='10000000-0000-0000-0000-000000000011';
 sale uuid; profile uuid; req uuid:=gen_random_uuid(); doc uuid; replacement uuid; queued jsonb; job record; cfg public.restaurant_fiscal_settings%ROWTYPE;
 day date:=(now() AT TIME ZONE 'America/Fortaleza')::date;
 data jsonb:='{"provider":"focus","environment":"homologacao","cnpj":"12345678000195","legal_name":"Empresa de teste","state_registration":"123","uf":"CE","time_zone":"America/Fortaleza","municipality_code":"2304400","tax_regime":"1","address":{"street":"Rua de teste","number":"100","district":"Centro","city":"Fortaleza","postalCode":"60000000"}}';
 payload jsonb:='{"cnpj_emitente":"12345678000195","items":[{"codigo_produto":"P1","descricao":"Produto de teste","quantidade_comercial":2,"valor_unitario_comercial":10,"valor_bruto":20}]}';
 payments jsonb;
BEGIN
 IF has_function_privilege('authenticated','fiscal_enqueue_sale(uuid,uuid,uuid,text,uuid,timestamptz,date,jsonb,bigint,jsonb,uuid[],text)','EXECUTE') OR has_function_privilege('anon','fiscal_set_enabled(uuid,uuid,text,boolean,text,uuid)','EXECUTE') THEN RAISE EXCEPTION 'Emissão exposta ao cliente'; END IF;
 SELECT id,payments_snapshot INTO sale,payments FROM fiscal_sales WHERE restaurant_id=rid;
 PERFORM fiscal_save_settings(rid,actor,data,'credencial-homologacao-cifrada');
 PERFORM fiscal_save_settings(rid,actor,data||'{"environment":"producao"}'::jsonb,'credencial-producao-cifrada');
 profile:=fiscal_save_product_profile(rid,actor,'homologacao',jsonb_build_object('item_id','30000000-0000-0000-0000-000000000011','valid_from',day-10,'valid_until',NULL,'ncm','21069090','cfop','5102','unit','UN','layout_version','fixture','tables_version','fixture','review_reference','Contabilidade de teste','attributes','{"icms_situacao_tributaria":"102"}'::jsonb));
 SELECT * INTO cfg FROM restaurant_fiscal_settings WHERE restaurant_id=rid AND environment='homologacao';
 PERFORM pg_temp.assert_fails(format('SELECT fiscal_enqueue_sale(%L,%L,%L,%L,%L,%L,%L,%L,2000,%L,ARRAY[%L]::uuid[],%L)',rid,actor,sale,'homologacao',req,cfg.updated_at,day,payload,payments,profile,repeat('a',64)),'desabilitada');
 PERFORM pg_temp.assert_fails(format('SELECT fiscal_set_enabled(%L,%L,%L,true,%L,NULL)',rid,'10000000-0000-0000-0000-000000000012','homologacao','Revisão fixture'),'responsável');
 PERFORM pg_temp.assert_fails(format('SELECT fiscal_set_enabled(%L,%L,%L,true,%L,NULL)',rid,actor,'producao','Revisão fixture'),'homologação');
 PERFORM fiscal_set_enabled(rid,actor,'homologacao',true,'Revisão contábil fixture');
 SELECT * INTO cfg FROM restaurant_fiscal_settings WHERE restaurant_id=rid AND environment='homologacao';
 PERFORM pg_temp.assert_fails(format('SELECT fiscal_enqueue_sale(%L,%L,%L,%L,%L,%L,%L,%L,1900,%L,ARRAY[%L]::uuid[],%L)',rid,actor,sale,'homologacao',req,cfg.updated_at,day,payload,payments,profile,repeat('a',64)),'Total fiscal');
 UPDATE archived_payments SET status='refunded' WHERE id='40000000-0000-0000-0000-000000000011';
 PERFORM pg_temp.assert_fails(format('SELECT fiscal_enqueue_sale(%L,%L,%L,%L,%L,%L,%L,%L,2000,%L,ARRAY[%L]::uuid[],%L)',rid,actor,sale,'homologacao',req,cfg.updated_at,day,payload,payments,profile,repeat('a',64)),'pagamentos mudaram');
 UPDATE archived_payments SET status='approved' WHERE id='40000000-0000-0000-0000-000000000011';
 queued:=fiscal_enqueue_sale(rid,actor,sale,'homologacao',req,cfg.updated_at,day,payload,2000,payments,ARRAY[profile],repeat('a',64)); doc:=(queued->>'id')::uuid;
 IF queued->>'state'<>'queued' OR (queued->>'existing')::boolean THEN RAISE EXCEPTION 'Não enfileirou nova nota'; END IF;
 IF (fiscal_enqueue_sale(rid,actor,sale,'homologacao',req,cfg.updated_at,day,payload,2000,payments,ARRAY[profile],repeat('a',64))->>'id')::uuid<>doc THEN RAISE EXCEPTION 'Duplicou solicitação'; END IF;
 IF (fiscal_enqueue_sale(rid,actor,sale,'homologacao',gen_random_uuid(),cfg.updated_at,day,payload,2000,payments,ARRAY[profile],repeat('a',64))->>'id')::uuid<>doc THEN RAISE EXCEPTION 'Duplicou consumo'; END IF;
 SELECT * INTO job FROM fiscal_outbox_claim(1);
 PERFORM fiscal_discard_unsent(rid,actor,doc);
 IF fiscal_outbox_begin_send(job.id,job.lease_token,payload||jsonb_build_object('data_emissao',now())) THEN RAISE EXCEPTION 'Enviou preparo descartado'; END IF;
 PERFORM pg_temp.assert_fails(format('SELECT fiscal_request_document_action(%L,%L,%L,%L,%L,NULL)',rid,actor,doc,gen_random_uuid(),'consult'),'descartado');
 queued:=fiscal_enqueue_sale(rid,actor,sale,'homologacao',gen_random_uuid(),cfg.updated_at,day,payload,2000,payments,ARRAY[profile],repeat('b',64)); replacement:=(queued->>'id')::uuid;
 IF replacement=doc THEN RAISE EXCEPTION 'Reutilizou referência descartada'; END IF;
 SELECT * INTO job FROM fiscal_outbox_claim(1);
 UPDATE archived_payments SET status='chargeback' WHERE id='40000000-0000-0000-0000-000000000011';
 IF fiscal_outbox_begin_send(job.id,job.lease_token,payload||jsonb_build_object('data_emissao',now())) THEN RAISE EXCEPTION 'Enviou após contestação'; END IF;
 UPDATE archived_payments SET status='approved' WHERE id='40000000-0000-0000-0000-000000000011';
 IF NOT fiscal_outbox_begin_send(job.id,job.lease_token,payload||jsonb_build_object('data_emissao',now())) THEN RAISE EXCEPTION 'Bloqueou venda válida'; END IF;
 PERFORM pg_temp.assert_fails(format('SELECT fiscal_discard_unsent(%L,%L,%L)',rid,actor,replacement),'envio já começou');
 IF NOT fiscal_outbox_finish(job.id,job.lease_token,jsonb_build_object('state','authorized','key','23261112345678000195'||repeat('3',24),'sefazCode','100','authorizedAt',now(),'protocol','123')) THEN RAISE EXCEPTION 'Não concluiu autorização de teste'; END IF;
 PERFORM fiscal_set_enabled(rid,actor,'homologacao',false,NULL);
 PERFORM fiscal_set_enabled(rid,actor,'producao',true,'Revisão produção fixture',replacement);
 IF NOT EXISTS(SELECT 1 FROM restaurant_fiscal_settings WHERE restaurant_id=rid AND environment='producao' AND enabled) THEN RAISE EXCEPTION 'Homologação da mesma revisão não habilitou produção'; END IF;
 PERFORM fiscal_set_enabled(rid,actor,'producao',false,NULL);
 UPDATE restaurant_fiscal_settings SET legal_name='Cadastro alterado após homologação' WHERE restaurant_id=rid AND environment='homologacao';
 PERFORM pg_temp.assert_fails(format('SELECT fiscal_set_enabled(%L,%L,%L,true,%L,%L)',rid,actor,'producao','Revisão fixture',replacement),'homologação');
 PERFORM pg_temp.assert_fails(format('UPDATE fiscal_documents SET preparation_fingerprint=%L WHERE id=%L',repeat('c',64),replacement),'imutáveis');
END $$;
ROLLBACK;
SELECT 'Emissão fiscal: permissões, idempotência e bloqueios passaram' AS resultado;
